steps.command:
install -d /etc/nginx/snippets && printf 'proxy_set_header X-Forwarded-For $remote_addr;
proxy_set_header X-Real-IP $remote_addr;
proxy_set_header X-Forwarded-Host $host;
proxy_set_header X-Original-URL "";
proxy_set_header X-Rewrite-URL "";
' > /etc/nginx/snippets/cme-922-trusted-headers.conf
